 "content": "from collections import deque

def _shape(cells):
    r0=min(r for r,c in cells); c0=min(c for r,c in cells)
    return frozenset((r-r0,c-c0) for r,c in cells)

def transform(grid):
    h,w=len(grid),len(grid[0])
    comps=[]; seen=set()
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==0 or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                x,y=q.pop(); cells.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    z=(x+dx,y+dy)
                    if 0<=z[0]<h and 0<=z[1]<w and grid[z[0]][z[1]]==color and z not in seen:
                        seen.add(z); q.append(z)
            comps.append((color,cells,_shape(cells)))
    targets={}
    for color,cells,shape in comps:
        if color!=1: targets.setdefault(shape,color)
    out=[row[:] for row in grid]
    for color,cells,shape in comps:
        if color==1 and shape in targets:
            for r,c in cells: out[r][c]=targets[shape]
    return out
